        "Когато говорим за студена замръзнала вода, латвийската дума обикновено е „лед“.",
        "Когато говорим за храна или десерт, das Eis в ежедневието много често означава сладолед.",
        "Контекстът обикновено ви казва веднага какво значение имате предвид.",
